package main

import "fmt"

// A model of how go test picks how many times to run a benchmark.
// Pretend one call always takes exactly 2 milliseconds (a slow call).
func main() {
	const cost = 2000000    // nanoseconds per call (pretend): 2 ms
	const goal = 1000000000 // run for at least 1 second = 1e9 ns
	n := 1
	for round := 1; ; round++ {
		total := n * cost
		fmt.Println(round, n, total)
		if total >= goal {
			break
		}
		next := goal * n / total // calls that would fill the goal
		next += next / 5         // aim 20% past it
		next = min(next, 100*n)  // but grow at most 100 times
		n = max(next, n+1)
	}
}

