package parcel

// Fee returns the delivery fee, in coins, for a parcel of kg kilograms.
func Fee(kg int) int {
	switch {
	case kg <= 1:
		return 3
	case kg <= 5:
		return 5
	default:
		return 5 + 2*(kg-5)
	}
}
